def matrix_spiral(m: list) -> list:
    if not m or not m[0]:
        return []

    result = []
    top, bottom = 0, len(m) - 1
    left, right = 0, len(m[0]) - 1

    while top <= bottom and left <= right:
        # Traverse from left to right along the top row
        for i in range(left, right + 1):
            result.append(m[top][i])
        top += 1

        # Traverse from top to bottom along the rightmost column
        for i in range(top, bottom + 1):
            result.append(m[i][right])
        right -= 1

        # Traverse from right to left along the bottom row, if there are still rows
        if top <= bottom:
            for i in range(right, left - 1, -1):
                result.append(m[bottom][i])
            bottom -= 1

        # Traverse from bottom to top along the leftmost column, if there are still columns
        if left <= right:
            for i in range(bottom, top - 1, -1):
                result.append(m[i][left])
            left += 1

    return result
```

