def invert_index(docs: dict) -> dict:
    index = {}
    for doc_id, text in docs.items():
        words = text.lower().split()
        for word in words:
            if word not in index:
                index[word] = []
            if doc_id not in index[word]:
                index[word].append(doc_id)
    for word in index:
        index[word].sort()
    return index
