def decode_string(s: str) -> str:
    stack = []
    i = 0
    while i < len(s):
        if s[i].isdigit():
            # Parse the number
            num = 0
            while i < len(s) and s[i].isdigit():
                num = num * 10 + int(s[i])
                i += 1
            stack.append(num)
        elif s[i] == '[':
            # Push an empty string onto the stack to mark the start of a new encoded segment
            stack.append('')
            i += 1
        elif s[i] == ']':
            # Pop the current string and repeat it k times
            current = stack.pop()
            k = stack.pop()
            # Append the repeated string to the previous level
            if stack:
                stack[-1] += current * k
            else:
                stack.append(current * k)
            i += 1
        else:
            # Regular character, append to the top of the stack
            if stack:
                stack[-1] += s[i]
            else:
                stack.append(s[i])
            i += 1
    return ''.join(stack)
```

